import{_ as r,l as i,o,c as s,v as e,p as l,x as n,d as E,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"库存与曲线","description":"","frontmatter":{"title":"库存与曲线","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/commodity-inventory.md","filePath":"quant/commodity-inventory.md","lastUpdated":1789023840000}'),A={name:"quant/commodity-inventory.md"};function p(c,a,B,u,m,g){const t=i("Mermaid");return o(),s("div",null,[a[1]||(a[1]=e('<h1 id="库存与曲线" tabindex="-1">库存与曲线 <a class="header-anchor" href="#库存与曲线" aria-label="Permalink to &quot;库存与曲线&quot;">​</a></h1><div class="epigraph"><p>现货升水是低库存的市场语言；曲线在紧张端变陡、波动在近月放大，都是同一条仓储供给曲线的不同投影。</p><footer>—— Working, The Theory of Price of Storage, AER, 1949；竞争性仓储与价格非线性见 Deaton &amp; Laroque, Review of Economic Studies, 1992；库存与溢价见 Gorton, Hayashi &amp; Rouwenhorst, Review of Finance, 2013</footer></div><p>商品期货曲线不是利率曲线的彩色复印。利率远期由无套利折现钉住；商品远期还要穿过仓储与现货可得性。Working（1949）给出最耐用的图：库存越高，现货相对远期越贴水；库存越低，现货升水越大，关系在低库存端更陡。Deaton 与 Laroque（1992, 1996）把竞争性仓储写成不能卖空的库存约束，解释价格的偏态与波动集群。Gorton、Hayashi 与 Rouwenhorst（2013）用三十一品种的实物库存证明：便利收益是库存的递减非线性函数，基差与既往收益能代理库存并预测期货溢价。本篇把<strong>可观测库存</strong>放到曲线与交易的中间，而不是把 backwardation 当成一个抽象标签。与 <a href="/quant/convenience-yield">商品便利收益</a> 的差别是：那篇定义 \\(y\\)，这篇处理 \\(I\\) 的测量、滞后与在曲线各段上的映射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>库存看起来是数量，实际是一套定义。原油有商业库存与战略储备、有库欣与全球水上浮仓；农产品有农场库存、仓库库存与「隐形」渠道库存；金属有交易所仓单与场外库存。报告日不同、口径修订、季节调整，使 \\(I_t\\) 与交易员脑中的「紧不紧」可以错位。用错误地点的库存去解释全球基准曲线，会得到稳定的伪关系。问题是选择与曲线交割机制匹配的库存：NYMEX WTI 先看库欣，CBOT 玉米看交割地仓单与 USDA 报告，LME 铜看取消仓单与区域溢价。</p><p>第二层是频率。曲线每日动，许多库存周度或月度。日度交易不得不用代理：基差本身、现货升贴水、近月波动、运费、仓单变化。Gorton 等人强调这些价格信号反映库存状态——用价格代理库存去做收益预测，在逻辑上不是循环，因为预测的是<strong>未来超额收益</strong>，而不是再预测当前基差。但若你的交易就是交易基差，再用基差当库存代理，就变成同义反复。</p><h3 id="working-曲线的非线性" tabindex="-1">Working 曲线的非线性 <a class="header-anchor" href="#working-曲线的非线性" aria-label="Permalink to &quot;Working 曲线的非线性&quot;">​</a></h3><p>把基差对库存水平做线性回归，在高库存区往往平坦、在低库存区陡峭。线性模型会低估紧张期的曲线响应，高估「再多一点库存也无所谓」的区域。这与期权的凸性相同：仓储是对短缺的看涨期权，Delta 在实值区变大。Pindyck（2001）把现货、远期、库存与波动写成联合动态：库存低时现货波动上升，Samuelson 效应（近月比远月更吵）加强。风险系统若用平行移动去压整条商品曲线，等于假设 \\(u\\)、\\(y\\) 与库存无关，紧张期的 P&amp;L 解释会失败。</p><p><span class="marginnote">交易所仓单可以因为注销去交割而「下降」，现货并未离开系统，只是从仓单统计走进了厂库。把注销仓单当消耗，会误报紧张。应同时看注销、在途与区域升贴水。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态变量优先用<strong>相对库存</strong>：对五年同期均值或对仓储容量的占用率，而不是绝对桶数。农业必须做季节调整，否则每年收获都会被当成一次「供给冲击」，见 <a href="/quant/seasonal-roll">季节性展期</a>。把相对库存分位映射到曲线：</p><ul><li>低分位：近端 backwardation 或现货升水，近月波动高，展期对多头有利；</li><li>中分位：曲线由 \\(r+u\\) 主导，弱 contango；</li><li>高分位：仓储约束（罐满、船位），远月可以出现超常 contango，现货贴水受仓储费上限制约。</li></ul><p>Gorton、Hayashi 与 Rouwenhorst 的两个检验可直接做成研究流程：用滞后库存水平回归随后的期货超额收益；按库存分位排序组合。他们还检验商业与非商业持仓，发现持仓不提供超出库存与价格信号的预测——复制时应报告这一「赛马」，避免把 CFTC 持仓当默认状态变量。</p><p>跨品种相对库存驱动 <a href="/quant/intercommodity-spread">跨品种价差</a>：汽油库存低、原油库存高，裂解应强。只看单一库存会漏掉加工约束。</p><h3 id="从库存到对冲比" tabindex="-1">从库存到对冲比 <a class="header-anchor" href="#从库存到对冲比" aria-label="Permalink to &quot;从库存到对冲比&quot;">​</a></h3><p>曲线不同区段对库存冲击的 beta 不同。近月合约对库欣库存的 EIA 周度意外敏感，远月更多反映全球供给与需求预期。关键利率式的做法是：把曲线分成近端、腹、远端，分别回归库存意外与宏观意外，得到分桶 01。对冲近端紧张应用近月与现货升贴水工具，而不是用远月互换「因为流动性好」。这与利率的 <a href="/quant/key-rate-duration">关键利率久期</a> 同构，状态变量从期限换成了库存。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>竞争性仓储者比较「今天卖现货」与「存起来、卖远期」。均衡时，库存的边际持有成本（含资金、仓储、损耗）等于预期现货升值加上便利。不能卖空库存意味着：便宜的现货可以吸入仓储，昂贵的短缺无法通过负库存创造出来，只能靠价格上涨与需求毁灭。因此价格在低库存有尖峰、在高库存有软地板（地板仍被仓储费与质量下降穿刺）。Deaton–Laroque 的模拟与农产品年度数据匹配的是这种非线性，而不是线性 AR。曲线是该均衡在不同到期上的投影：近端看见今天的 \\(I\\)，远端看见补库与新作预期。</p><p>金融化改变谁持有<strong>期货</strong>，不自动改变谁持有<strong>库存</strong>。若指数资金持续做多近月，可以把 \\(F\\) 相对 \\(S\\) 抬高，反演的 \\(y\\) 下降，看起来像「库存没那么紧」。这是金融需求，应与实物库存分列。Gorton 与 Rouwenhorst（2006）把商品期货当成资产类别时，超额来自风险溢价与展期，前提仍是期货与库存通过仓储相连；当连接被挤仓或交割故障打断（负油价那种极限），库存—曲线映射暂时作废。</p><p><span class="marginnote">凯恩斯正常 backwardation 预测「净套保空头 → 期货低于期望现货」。库存理论预测「低库存 → 高便利 → 曲线近端升水，且随后超额往往更高」。二者可同时成立，但 Gorton–Hayashi–Rouwenhorst 的赛马把预测权给了库存这一边。</span></p><h3 id="报告日与测量误差" tabindex="-1">报告日与测量误差 <a class="header-anchor" href="#报告日与测量误差" aria-label="Permalink to &quot;报告日与测量误差&quot;">​</a></h3><p>EIA、API、USDA WASDE、LME 仓单，都是带噪声的测量。意外相对的是市场隐含库存（可从曲线反演），不是相对上次公布。若曲线已定价一次大幅去库，公布「符合预期的去库」不应再推动近月。把公布值对滞后公布值的差分当因子，会把预期内的季节走库当成 alpha。正确的事件研究用公布减调查中位数，再看近端曲线的即时反应。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>战略储备释放、出口禁令、管道出险，使公开商业库存与真实可获得库存脱节。浮仓与保税区在某些品种上可以大于交易所库存。新兴市场农产品的官方库存质量参差，用美国库存去交易全球小麦曲线会错配。电、天气、运费没有可比较的库存状态，不应塞进同一张 Working 图。</p><p>回测切忌用修订后的库存序列在过去做决策。美国库存常有修订，实时交易只能用初次公布。曲线一侧必须用当时的合约价格，不能用主连连续行情，否则换月跳空会被当成库存冲击。满罐约束是硬的：高库存端的 contango 可以突然被仓储费与强制抛售主导，线性外推「再累库基差再弱」会在物理极限处翻车。</p><p><span class="marginnote">库存是缓慢状态，不是每日 alpha 信号。日度交易应交易<strong>库存意外</strong>与<strong>曲线相对该状态是否错价</strong>；把库存分位当成每天翻转的 z-score，会在报告间歇期反复挨打。</span></p>',26)),(o(),l(h,null,{default:n(()=>[d(t,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%9B%B8%E5%AF%B9%E5%BA%93%E5%AD%98%20I%22%5D%20--%3E%20Y%5B%22%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%20y(I)%22%5D%0A%20%20Y%20--%3E%20NEAR%5B%22%E8%BF%91%E7%AB%AF%E6%9B%B2%E7%BA%BF%20%2F%20%E7%8E%B0%E8%B4%A7%E5%8D%87%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20I%20--%3E%20VOL%5B%22%E8%BF%91%E6%9C%88%E6%B3%A2%E5%8A%A8%20%2F%20Samuelson%22%5D%0A%20%20I%20--%3E%20RP%5B%22%E9%9A%8F%E5%90%8E%E6%9C%9F%E8%B4%A7%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20PROXY%5B%22%E5%9F%BA%E5%B7%AE%E4%B8%8E%E4%BB%93%E5%8D%95%E4%BB%A3%E7%90%86%22%5D%20--%3E%20I%0A%20%20RPT%5B%22%E5%91%A8%E5%BA%A6%E6%9C%88%E5%BA%A6%E6%8A%A5%E5%91%8A%E6%84%8F%E5%A4%96%22%5D%20--%3E%20NEAR%0A%20%20FULL%5B%22%E6%BB%A1%E7%BD%90%20%2F%20%E9%9B%B6%E5%BA%93%E5%AD%98%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20NL%5B%22%E9%9D%9E%E7%BA%BF%E6%80%A7%3A%20%E9%99%A1%E7%9A%84%E7%B4%A7%E5%BC%A0%E7%AB%AF%22%5D%0A%20%20NL%20--%3E%20Y%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Working 曲线：库存与现货升水反向，且在低库存端非线性变陡；这是仓储供给，不是装饰性相关。</li><li>Deaton–Laroque 说明不能卖空库存如何产生偏态与波动集群；Pindyck 把波动与曲线放进同一动态。</li><li>Gorton、Hayashi 与 Rouwenhorst（2013）验证 \\(y(I)\\) 与「库存预测溢价、持仓不额外预测」。</li><li>测量必须匹配交割地点与实时口径；价格代理库存只在预测未来收益时合法，不能用来解释当前基差本身。</li><li>金融持仓冲击与实物库存应分列；极限仓储失效时映射暂停。</li><li>出处：Working, <em>AER</em>, 1949；Deaton and Laroque, <em>Review of Economic Studies</em>, 1992 与 <em>JPE</em>, 1996；Pindyck, <em>The Energy Journal</em>, 2001；Gorton, Hayashi and Rouwenhorst, <em>Review of Finance</em>, 2013；Gorton and Rouwenhorst, <em>FAJ</em>, 2006。</li></ul>',2))])}const q=r(A,[["render",p]]);export{f as __pageData,q as default};
